from pathlib import Path
import os,subprocess,json,collections
R=Path('/home/runner/workspace');D=R/'tools/dr_isl/isl20';s='scenario-fc100-islanded-zero-hot-v2'
def run(mode):
 env=dict(os.environ,PYTHONHASHSEED='1729',PYTHONDONTWRITEBYTECODE='1',ISL20_MODE=mode)
 p=subprocess.run(['python','/tmp/isl20-scratch/worker.py',str(R),s,'app','5fbf357'],env=env,capture_output=True,text=True,check=True)
 return [json.loads(l)['physical'] for l in p.stdout.splitlines() if json.loads(l)['kind']=='tick']
a=run('base');b=run('droop');out=[];counts=collections.Counter()
for x,y in zip(a,b):
 fields={k:{'before':x[k],'after':y[k]} for k in x if k not in ('frequency_hz','frequency_valid','frequency_forcing_mw','advisory_telemetry','fabric_modal','wall_stamp_utc','insufficient_reserve_proposal_id') and x[k]!=y[k]}
 if fields:out.append({'tick':x['tick_index'],'differences':fields});counts.update(fields.keys())
f=D/'FC_ZERO_COUNTERFACTUAL_DIFFERENCES.json';f.write_text(json.dumps({'ticks_before':len(a),'ticks_after':len(b),'field_counts':counts,'differing_ticks':out,'ledger_identical':all(x['physical_balance']==y['physical_balance'] for x,y in zip(a,b))},indent=2)+'\n');print(json.dumps(dict(counts)));print('ledger identical',all(x['physical_balance']==y['physical_balance'] for x,y in zip(a,b)))
